using AcxiomCRM.Data; using AcxiomCRM.Models; using AcxiomCRM.Services; using Microsoft.AspNetCore.Authorization; using Microsoft.AspNetCore.Mvc; using Microsoft.EntityFrameworkCore; using System.Security.Claims;
namespace AcxiomCRM.Controllers;
[Authorize] public class LeadsController:Controller { private readonly ApplicationDbContext _db; private readonly IAuditService _audit; public LeadsController(ApplicationDbContext db,IAuditService audit){_db=db;_audit=audit;}
 public async Task<IActionResult> Index(string? q,string? status,int page=1){var query=_db.Leads.AsQueryable(); if(!User.IsInRole("Admin")&&!User.IsInRole("Manager")){var uid=User.FindFirstValue(ClaimTypes.NameIdentifier); query=query.Where(x=>x.AssignedTo==uid);} if(!string.IsNullOrWhiteSpace(q)){var s=q.Trim(); query=query.Where(x=>x.LeadName.Contains(s)||(x.CompanyName!=null&&x.CompanyName.Contains(s))||(x.Email!=null&&x.Email.Contains(s)));} if(!string.IsNullOrWhiteSpace(status)) query=query.Where(x=>x.Status==status); ViewBag.Query=q;ViewBag.Status=status;ViewBag.Page=page;ViewBag.Pages=(int)Math.Ceiling(await query.CountAsync()/10.0);return View(await query.OrderByDescending(x=>x.Id).Skip((Math.Max(1,page)-1)*10).Take(10).ToListAsync());}
 public async Task<IActionResult> Details(int id){var item=await _db.Leads.FindAsync(id);if(item==null)return NotFound();return View(item);}
 
 [HttpPost,ValidateAntiForgeryToken] public async Task<IActionResult> Create(Lead item){if(string.IsNullOrWhiteSpace(item.LeadCode))item.LeadCode="LED-"+Guid.NewGuid().ToString("N")[..8].ToUpper();if(!new[]{"New","Contacted","Qualified","Unqualified","Converted","Lost"}.Contains(item.Status))ModelState.AddModelError(nameof(item.Status),"Select a valid lead status.");if(item.Status=="Converted")item.IsConverted=true;if(!ModelState.IsValid)return View(item);item.CreatedBy=User.FindFirstValue(ClaimTypes.NameIdentifier);if(item is Lead assigned && string.IsNullOrEmpty(assigned.AssignedTo)){assigned.AssignedTo=item.CreatedBy;}_db.Leads.Add(item);try{await _db.SaveChangesAsync();await _audit.WriteAsync("Create","Lead",item.Id.ToString(),newValue:System.Text.Json.JsonSerializer.Serialize(item));TempData["Success"]="Lead created successfully.";return RedirectToAction(nameof(Index));}catch(DbUpdateException){ModelState.AddModelError("","Could not save this record. Check for duplicate values and related records.");return View(item);}}
 public async Task<IActionResult> Edit(int id){var item=await _db.Leads.FindAsync(id);return item==null?NotFound():View(item);}
 [HttpPost,ValidateAntiForgeryToken] public async Task<IActionResult> Edit(int id,Lead item){if(id!=item.Id)return BadRequest();if(string.IsNullOrWhiteSpace(item.LeadCode))item.LeadCode="LED-"+Guid.NewGuid().ToString("N")[..8].ToUpper();if(!new[]{"New","Contacted","Qualified","Unqualified","Converted","Lost"}.Contains(item.Status))ModelState.AddModelError(nameof(item.Status),"Select a valid lead status.");if(item.Status=="Converted")item.IsConverted=true;if(!ModelState.IsValid)return View(item);var old=await _db.Leads.AsNoTracking().FirstOrDefaultAsync(x=>x.Id==id);if(old==null)return NotFound();_db.Entry(item).State=EntityState.Modified;_db.Entry(item).Property(x=>x.CreatedDate).IsModified=false;_db.Entry(item).Property(x=>x.CreatedBy).IsModified=false;try{await _db.SaveChangesAsync();await _audit.WriteAsync("Update","Lead",id.ToString(),System.Text.Json.JsonSerializer.Serialize(old),System.Text.Json.JsonSerializer.Serialize(item));TempData["Success"]="Lead updated successfully.";return RedirectToAction(nameof(Index));}catch(DbUpdateException){ModelState.AddModelError("","Could not update this record. Check duplicate values and relationships.");return View(item);}}
 [HttpPost,ValidateAntiForgeryToken] public async Task<IActionResult> Delete(int id){var item=await _db.Leads.FindAsync(id);if(item==null)return NotFound();var old=System.Text.Json.JsonSerializer.Serialize(item);item.Status="Lost";try{await _db.SaveChangesAsync();await _audit.WriteAsync("Delete/Deactivate","Lead",id.ToString(),old);TempData["Success"]="Mark lead lost completed.";}catch(DbUpdateException){TempData["Error"]="This record is referenced by other records and cannot be deleted. Deactivate it instead.";}return RedirectToAction(nameof(Index));}

}
